function startOscillation() {
  if (oscillating) return;
  oscillating = true; phase = 0; drawAll();
  (function tick() {
    if (!oscillating) return;
    phase += 0.06; drawAll();
    animId = requestAnimationFrame(tick);
  })();
}
function stopOscillation() {
  oscillating = false;
  if (animId) { cancelAnimationFrame(animId); animId = null; }
  drawAll();
}

function setMode(n) {
  currentN = n;
  document.getElementById('modeStepInput').value = n;
  var btns = document.querySelectorAll('.mode-btn');
  for (var i = 0; i < btns.length; i++) btns[i].classList.toggle('active', +btns[i].getAttribute('data-n') === n);
  drawAll();
}
function update_lengthL(v) { currentL = v; drawAll(); }
function toggle_oscillate(on) { if (on) startOscillation(); else stopOscillation(); }

function goToStep(idx) {
  currentStep = idx;
  var s = steps[idx];
  currentN = s.n; currentL = s.L;
  document.getElementById('modeStepInput').value = s.n;
  document.getElementById('lengthLInput').value = s.L;
  document.getElementById('lengthLVal').value = s.L.toFixed(1);
  var btns = document.querySelectorAll('.mode-btn');
  for (var i = 0; i < btns.length; i++) btns[i].classList.toggle('active', +btns[i].getAttribute('data-n') === s.n);
  if (idx === 2) {
    document.getElementById('oscillateInput').checked = true;
    startOscillation();
  } else {
    document.getElementById('oscillateInput').checked = false;
    stopOscillation();
  }
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (idx+1) + ' / ' + steps.length;
}
function nextStep() { goToStep(Math.min(currentStep+1, steps.length-1)); }
function prevStep() { goToStep(Math.max(currentStep-1, 0)); }

goToStep(0);
window.__markRendered();
// @FIGURE_CODE_END

