<label>String length <i>L</i>: <output id="lengthLVal">2.0</output>
<input id="lengthLInput" type="range" min="1" max="4" step="0.1" value="2" oninput="document.getElementById('lengthLVal').value=(+this.value).toFixed(1);update_lengthL(+this.value)">
</label>
