// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%','100%');
var W = 900, H = 520;
draw.viewbox(0, 0, W, H);

var currentN = 1, currentL = 2, oscillating = false, animId = null, phase = 0, currentStep = 0;
var centerX = 370, pxPerL = 100, centerY = 300, amplitude = 55, refLineY = 70, arrowY = 38;

function sLeft() { return centerX - (currentL * pxPerL) / 2; }
function sRight() { return centerX + (currentL * pxPerL) / 2; }

var bgGroup = draw.group();
var refGroup = draw.group();
var waveGroup = draw.group();
var nodeGroup = draw.group();
var labelGroup = draw.group();
var eqGroup = draw.group();
var hoverGroup = draw.group();

var hoverRect = hoverGroup.rect(100, 140).fill('transparent').css('cursor','pointer');
hoverRect.on('mousemove', function(e) {
  var svgPt = draw.node.createSVGPoint();
  svgPt.x = e.clientX; svgPt.y = e.clientY;
  var ctm = draw.node.getScreenCTM();
  if (!ctm) return;
  var pt = svgPt.matrixTransform(ctm.inverse());
  var sl = sLeft(), sr = sRight(), len = sr - sl, nearNode = false;
  if (Math.abs(pt.x - sl) < 12 && Math.abs(pt.y - centerY) < 12) nearNode = true;
  if (Math.abs(pt.x - sr) < 12 && Math.abs(pt.y - centerY) < 12) nearNode = true;
  for (var k = 1; k < currentN; k++) {
    var nx = sl + (k / currentN) * len;
    if (Math.abs(pt.x - nx) < 9 && Math.abs(pt.y - centerY) < 9) nearNode = true;
  }
  if (nearNode) {
    showTooltip('Node: displacement is always zero at this point', e);
  } else {
    showTooltip('Mode n = ' + currentN + '  |  \u03BB' + currentN + ' = 2L/' + currentN + ' = ' + (2*currentL/currentN).toFixed(2), e);
  }
});
hoverRect.on('mouseleave', function() { hideTooltip(); });
hoverRect.on('click', function() {
  var ord = currentN === 1 ? '1st' : currentN === 2 ? '2nd' : currentN === 3 ? '3rd' : '4th';
  showPopup('Standing Wave \u2014 Mode n = ' + currentN,
    'This is the ' + ord + ' harmonic (mode n = ' + currentN + '). The string contains exactly ' + currentN +
    ' half-wavelength(s) between the fixed ends, so n/2 \u00B7 \u03BB = L, giving \u03BB = 2L/' + currentN +
    ' = ' + (2*currentL/currentN).toFixed(2) + ' units. Nodes (zero displacement) sit at every half-wavelength boundary; antinodes (maximum displacement) occur at the peaks of each loop.');
});

var steps = [
  { narration: 'For n = 1 exactly one half-wavelength fits between the pinned ends, so (1/2)\u03BB\u2081 = L and \u03BB\u2081 = 2L. The two envelope curves show the full sweep; the ends are the only nodes.', n: 1, L: 2 },
  { narration: 'Step to n = 2, then n = 3 and n = 4: each step packs one more half-wavelength into the same L, adding one interior node and one more loop, with the equation tracking n/2 \u00B7 \u03BB\u2099 = L.', n: 3, L: 2 },
  { narration: 'Press play: the string oscillates between the envelope curves. Every node (endpoints and interior crossings) stays perfectly still while the antinodes at the loop peaks swing widest.', n: 3, L: 2 },
  { narration: 'Drag the L slider: the pattern and its wavelength \u03BB\u2099 = 2L/n stretch or shrink together, confirming that the fixed length L sets the actual wavelength.', n: 2, L: 3.4 }
];

function drawAll() {
  bgGroup.clear(); refGroup.clear(); waveGroup.clear();
  nodeGroup.clear(); labelGroup.clear(); eqGroup.clear();

  var sl = sLeft(), sr = sRight(), len = sr - sl, n = currentN;
  hoverRect.attr({ x: sl - 12, y: centerY - amplitude - 18, width: len + 24, height: amplitude * 2 + 36 });

  // Thumbnails
  var tX = 25, tW = 65, tH = 12, tY0 = 130;
  for (var m = 1; m <= 4; m++) {
    var ty = tY0 + (m - 1) * 35, pts = [];
    for (var i = 0; i <= 40; i++) {
      var t = i / 40;
      pts.push((tX + t * tW).toFixed(1) + ',' + (ty - tH * Math.sin(m * Math.PI * t)).toFixed(1));
    }
    var act = (m === n);
    bgGroup.polyline(pts.join(' ')).fill('none').stroke({ color: act ? '#2c5f8a' : '#c8c8c8', width: act ? 1.8 : 1 });
    bgGroup.text('n=' + m).attr({ x: tX + tW + 4, y: ty + 4, 'font-size': 10, fill: act ? '#2c5f8a' : '#aaa', 'font-family': 'sans-serif' });
  }

  // Reference line + nodes
  refGroup.line(sl, refLineY, sr, refLineY).stroke({ color: '#4a7ab5', width: 2 });
  refGroup.circle(7).center(sl, refLineY).fill('#222');
  refGroup.circle(7).center(sr, refLineY).fill('#222');
  refGroup.text('Node').attr({ x: sl - 17, y: refLineY + 16, 'font-size': 13, fill: '#333', 'font-family': 'sans-serif' });
  refGroup.text('Node').attr({ x: sr - 17, y: refLineY + 16, 'font-size': 13, fill: '#333', 'font-family': 'sans-serif' });

  // L arrow
  refGroup.line(sl, arrowY, sr, arrowY).stroke({ color: '#333', width: 1.2 });
  refGroup.polygon(sl + ',' + arrowY + ' ' + (sl+7) + ',' + (arrowY-3.5) + ' ' + (sl+7) + ',' + (arrowY+3.5)).fill('#333');
  refGroup.polygon(sr + ',' + arrowY + ' ' + (sr-7) + ',' + (arrowY-3.5) + ' ' + (sr-7) + ',' + (arrowY+3.5)).fill('#333');
  refGroup.line(sl, arrowY-5, sl, arrowY+5).stroke({ color: '#333', width: 1.2 });
  refGroup.line(sr, arrowY-5, sr, arrowY+5).stroke({ color: '#333', width: 1.2 });
  refGroup.text('L').attr({ x: centerX - 5, y: arrowY - 8, 'font-size': 16, fill: '#333', 'font-style': 'italic', 'font-family': 'Georgia,serif' });

  // Equilibrium line
  waveGroup.line(sl, centerY, sr, centerY).stroke({ color: '#ddd', width: 0.7, dasharray: '4,3' });

  // Wave
  var S = 250, uPts = [], lPts = [];
  for (var i = 0; i <= S; i++) {
    var t = i / S, x = sl + t * len, yv = Math.sin(n * Math.PI * t);
    uPts.push(x.toFixed(1) + ',' + (centerY - amplitude * yv).toFixed(1));
    lPts.push(x.toFixed(1) + ',' + (centerY + amplitude * yv).toFixed(1));
  }
  if (oscillating) {
    waveGroup.polyline(uPts.join(' ')).fill('none').stroke({ color: '#d4e4f0', width: 1.5 });
    waveGroup.polyline(lPts.join(' ')).fill('none').stroke({ color: '#d4e4f0', width: 1.5 });
    var cp = Math.cos(phase), oPts = [];
    for (var i = 0; i <= S; i++) {
      var t = i / S, x = sl + t * len, yv = Math.sin(n * Math.PI * t) * cp;
      oPts.push(x.toFixed(1) + ',' + (centerY - amplitude * yv).toFixed(1));
    }
    waveGroup.polyline(oPts.join(' ')).fill('none').stroke({ color: '#2c5f8a', width: 2.5, linecap: 'round', linejoin: 'round' });
  } else {
    waveGroup.polyline(uPts.join(' ')).fill('none').stroke({ color: '#2c5f8a', width: 2.5, linecap: 'round', linejoin: 'round' });
    waveGroup.polyline(lPts.join(' ')).fill('none').stroke({ color: '#a8c8e0', width: 2, linecap: 'round', linejoin: 'round' });
  }

  // Node dots
  nodeGroup.circle(8).center(sl, centerY).fill('#222');
  nodeGroup.circle(8).center(sr, centerY).fill('#222');
  for (var k = 1; k < n; k++) {
    nodeGroup.circle(5).center(sl + (k / n) * len, centerY).fill('#555');
  }

  // Left label
  labelGroup.text(function(add) {
    add.tspan('n').attr({ 'font-style': 'italic', 'font-size': 17, 'font-family': 'Georgia,serif' });
    add.tspan(' = ' + n).attr({ 'font-size': 17, 'font-family': 'Georgia,serif' });
  }).attr({ x: 25, y: centerY + 6, fill: '#333' });

  // Equations
  var eqX = 620, fs = 15;
  var e1y = centerY - 25, e2y = centerY + 22;

  // Eq1: (n/2) λ_n = L
  var fcx = eqX + 10;
  eqGroup.text(String(n)).attr({ x: fcx, y: e1y - 2, 'font-size': fs*0.8, fill: '#333', 'font-family': 'Georgia,serif', 'text-anchor': 'middle' });
  eqGroup.line(fcx-9, e1y+3, fcx+9, e1y+3).stroke({ color: '#333', width: 1 });
  eqGroup.text('2').attr({ x: fcx, y: e1y+15, 'font-size': fs*0.8, fill: '#333', 'font-family': 'Georgia,serif', 'text-anchor': 'middle' });
  var lx = fcx + 15;
  eqGroup.text('\u03BB').attr({ x: lx, y: e1y+8, 'font-size': fs, fill: '#333', 'font-style': 'italic', 'font-family': 'Georgia,serif' });
  eqGroup.text(String(n)).attr({ x: lx+fs*0.55, y: e1y+13, 'font-size': fs*0.65, fill: '#333', 'font-family': 'Georgia,serif' });
  eqGroup.text('= L').attr({ x: lx+fs*0.55+fs*0.5+5, y: e1y+8, 'font-size': fs, fill: '#333', 'font-style': 'italic', 'font-family': 'Georgia,serif' });

  // Eq2: λ_n = (2/n) L
  var lx2 = eqX;
  eqGroup.text('\u03BB').attr({ x: lx2, y: e2y+8, 'font-size': fs, fill: '#333', 'font-style': 'italic', 'font-family': 'Georgia,serif' });
  eqGroup.text(String(n)).attr({ x: lx2+fs*0.55, y: e2y+13, 'font-size': fs*0.65, fill: '#333', 'font-family': 'Georgia,serif' });
  var eqx2 = lx2 + fs*0.55 + fs*0.5 + 5;
  eqGroup.text('=').attr({ x: eqx2, y: e2y+8, 'font-size': fs, fill: '#333', 'font-family': 'Georgia,serif' });
  var fcx2 = eqx2 + fs*0.7 + 12;
  eqGroup.text('2').attr({ x: fcx2, y: e2y-2, 'font-size': fs*0.8, fill: '#333', 'font-family': 'Georgia,serif', 'text-anchor': 'middle' });
  eqGroup.line(fcx2-9, e2y+3, fcx2+9, e2y+3).stroke({ color: '#333', width: 1 });
  eqGroup.text(String(n)).attr({ x: fcx2, y: e2y+15, 'font-size': fs*0.8, fill: '#333', 'font-family': 'Georgia,serif', 'text-anchor': 'middle' });
  eqGroup.text('L').attr({ x: fcx2+14, y: e2y+8, 'font-size': fs, fill: '#333', 'font-style': 'italic', 'font-family': 'Georgia,serif' });

  // General formula
  var gx = 590, gy = 488;
  eqGroup.text('\u03BB').attr({ x: gx, y: gy, 'font-size': 14, fill: '#333', 'font-style': 'italic', 'font-family': 'Georgia,serif' });
  eqGroup.text('n').attr({ x: gx+9, y: gy+5, 'font-size': 10, fill: '#333', 'font-style': 'italic', 'font-family': 'Georgia,serif' });
  eqGroup.text('=').attr({ x: gx+20, y: gy, 'font-size': 14, fill: '#333', 'font-family': 'Georgia,serif' });
  var gfc = gx + 38;
  eqGroup.text('2').attr({ x: gfc, y: gy-7, 'font-size': 12, fill: '#333', 'font-family': 'Georgia,serif', 'text-anchor': 'middle' });
  eqGroup.line(gfc-8, gy-2, gfc+8, gy-2).stroke({ color: '#333', width: 1 });
  eqGroup.text('n').attr({ x: gfc, y: gy+10, 'font-size': 12, fill: '#333', 'font-style': 'italic', 'font-family': 'Georgia,serif', 'text-anchor': 'middle' });
  eqGroup.text('L').attr({ x: gfc+13, y: gy, 'font-size': 14, fill: '#333', 'font-style': 'italic', 'font-family': 'Georgia,serif' });
  eqGroup.text(',  n = 1, 2, 3, \u2026').attr({ x: gfc+27, y: gy, 'font-size': 12, fill: '#333', 'font-family': 'Georgia,serif' });
}

function startOscillation() {
  if (oscillating) return;
  oscillating = true; phase = 0; drawAll();
  (function tick() {
    if (!oscillating) return;
    phase += 0.06; drawAll();
    animId = requestAnimationFrame(tick);
  })();
}
function stopOscillation() {
  oscillating = false;
  if (animId) { cancelAnimationFrame(animId); animId = null; }
  drawAll();
}

function setMode(n) {
  currentN = n;
  document.getElementById('modeStepInput').value = n;
  var btns = document.querySelectorAll('.mode-btn');
  for (var i = 0; i < btns.length; i++) btns[i].classList.toggle('active', +btns[i].getAttribute('data-n') === n);
  drawAll();
}
function update_lengthL(v) { currentL = v; drawAll(); }
function toggle_oscillate(on) { if (on) startOscillation(); else stopOscillation(); }

function goToStep(idx) {
  currentStep = idx;
  var s = steps[idx];
  currentN = s.n; currentL = s.L;
  document.getElementById('modeStepInput').value = s.n;
  document.getElementById('lengthLInput').value = s.L;
  document.getElementById('lengthLVal').value = s.L.toFixed(1);
  var btns = document.querySelectorAll('.mode-btn');
  for (var i = 0; i < btns.length; i++) btns[i].classList.toggle('active', +btns[i].getAttribute('data-n') === s.n);
  if (idx === 2) {
    document.getElementById('oscillateInput').checked = true;
    startOscillation();
  } else {
    document.getElementById('oscillateInput').checked = false;
    stopOscillation();
  }
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (idx+1) + ' / ' + steps.length;
}
function nextStep() { goToStep(Math.min(currentStep+1, steps.length-1)); }
function prevStep() { goToStep(Math.max(currentStep-1, 0)); }

goToStep(0);
window.__markRendered();
