      var t = i / S, x = sl + t * len, yv = Math.sin(m * Math.PI * t);
      uPts.push(x.toFixed(1) + ',' + (cy - amp * yv).toFixed(1));
      lPts.push(x.toFixed(1) + ',' + (cy + amp * yv).toFixed(1));
    }

    if (isHl && oscillating) {
      waveGroups[idx].polyline(uPts.join(' ')).fill('none').stroke({ color: '#d8e8f4', width: 1.2 });
      waveGroups[idx].polyline(lPts.join(' ')).fill('none').stroke({ color: '#d8e8f4', width: 1.2 });
      var cp = Math.cos(phase), oPts = [];
      for (var i = 0; i <= S; i++) {
        var t = i / S, x = sl + t * len, yv = Math.sin(m * Math.PI * t) * cp;
        oPts.push(x.toFixed(1) + ',' + (cy - amp * yv).toFixed(1));
      }
      waveGroups[idx].polyline(oPts.join(' ')).fill('none').stroke({ color: darkColor, width: darkW, linecap: 'round', linejoin: 'round' });
    } else {
      waveGroups[idx].polyline(uPts.join(' ')).fill('none').stroke({ color: darkColor, width: darkW, linecap: 'round', linejoin: 'round' });
      waveGroups[idx].polyline(lPts.join(' ')).fill('none').stroke({ color: paleColor, width: paleW, linecap: 'round', linejoin: 'round' });
    }

    // Node dots
    nodeGroups[idx].circle(isHl ? 9 : 7).center(sl, cy).fill('#222');
    nodeGroups[idx].circle(isHl ? 9 : 7).center(sr, cy).fill('#222');
    for (var k = 1; k < m; k++) {
      nodeGroups[idx].circle(isHl ? 6 : 5).center(sl + (k / m) * len, cy).fill('#444');
    }

    // Left label "n = m"
    labelGroups[idx].text(function(add) {
      add.tspan('n').attr({ 'font-style': 'italic', 'font-size': 16, 'font-family': 'Georgia,serif' });
      add.tspan(' = ' + m).attr({ 'font-size': 16, 'font-family': 'Georgia,serif' });
    }).attr({ x: 55, y: cy + 6, fill: isHl ? '#1a3a6b' : '#555' });

    // Equations for this row
    var fs = 15;
    var e1y = cy - 18, e2y = cy + 22;

    // Eq1: (n/2) λ_n = L
    var fracW1 = drawFraction(eqGroups[idx], eqX + 12, e1y, String(m), '2', fs * 0.85);
    var lx1 = eqX + 12 + fracW1 / 2 + 6;
    eqGroups[idx].text('\u03BB').attr({ x: lx1, y: e1y + 5, 'font-size': fs, fill: '#333', 'font-style': 'italic', 'font-family': 'Georgia,serif' });
    eqGroups[idx].text(String(m)).attr({ x: lx1 + fs * 0.6, y: e1y + 10, 'font-size': fs * 0.65, fill: '#333', 'font-family': 'Georgia,serif' });
    eqGroups[idx].text('= L').attr({ x: lx1 + fs * 0.6 + fs * 0.5 + 6, y: e1y + 5, 'font-size': fs, fill: '#333', 'font-style': 'italic', 'font-family': 'Georgia,serif' });

    // Eq2: λ_n = (2/n) L
    var lx2 = eqX;
    eqGroups[idx].text('\u03BB').attr({ x: lx2, y: e2y + 5, 'font-size': fs, fill: '#333', 'font-style': 'italic', 'font-family': 'Georgia,serif' });
    eqGroups[idx].text(String(m)).attr({ x: lx2 + fs * 0.6, y: e2y + 10, 'font-size': fs * 0.65, fill: '#333', 'font-family': 'Georgia,serif' });
    var eqx2 = lx2 + fs * 0.6 + fs * 0.5 + 6;
    eqGroups[idx].text('=').attr({ x: eqx2, y: e2y + 5, 'font-size': fs, fill: '#333', 'font-family': 'Georgia,serif' });
    var fcx2 = eqx2 + fs * 0.8 + 14;
    drawFraction(eqGroups[idx], fcx2, e2y, '2', String(m), fs * 0.85);
    eqGroups[idx].text('L').attr({ x: fcx2 + fracW1 / 2 + 8, y: e2y + 5, 'font-size': fs, fill: '#333', 'font-style': 'italic', 'font-family': 'Georgia,serif' });
  }

  // General formula at bottom right
  var gx = 600, gy = genFormulaY;
  genGroup.text('\u03BB').attr({ x: gx, y: gy, 'font-size': 15, fill: '#333', 'font-style': 'italic', 'font-family': 'Georgia,serif' });
  genGroup.text('n').attr({ x: gx + 10, y: gy + 5, 'font-size': 11, fill: '#333', 'font-style': 'italic', 'font-family': 'Georgia,serif' });
  genGroup.text('=').attr({ x: gx + 22, y: gy, 'font-size': 15, fill: '#333', 'font-family': 'Georgia,serif' });
  var gfc = gx + 42;
  drawFraction(genGroup, gfc, gy, '2', 'n', 13);
  genGroup.text('L').attr({ x: gfc + 16, y: gy, 'font-size': 15, fill: '#333', 'font-style': 'italic', 'font-family': 'Georgia,serif' });
  genGroup.text(',   n = 1, 2, 3, \u2026').attr({ x: gfc + 32, y: gy, 'font-size': 13, fill: '#333', 'font-family': 'Georgia,serif' });
}

function startOscillation() {
  if (oscillating) return;
  oscillating = true; phase = 0; drawAll();
  (function tick() {
    if (!oscillating) return;
    phase += 0.055; drawAll();
    animId = requestAnimationFrame(tick);
  })();
}
function stopOscillation() {
  oscillating = false;
  if (animId) { cancelAnimationFrame(animId); animId = null; }
  drawAll();
}

function setMode(n) {
  currentN = n;
  var btns = document.querySelectorAll('.mode-btn');
  for (var i = 0; i < btns.length; i++) btns[i].classList.toggle('active', +btns[i].getAttribute('data-n') === n);
  drawAll();
}
function update_lengthL(v) { currentL = v; drawAll(); }
function toggle_oscillate(on) { if (on) startOscillation(); else stopOscillation(); }

function goToStep(idx) {
  currentStep = idx;
  var s = steps[idx];
  currentN = s.n; currentL = s.L;
  document.getElementById('lengthLInput').value = s.L;
  document.getElementById('lengthLVal').value = s.L.toFixed(1);
  var btns = document.querySelectorAll('.mode-btn');
  for (var i = 0; i < btns.length; i++) btns[i].classList.toggle('active', +btns[i].getAttribute('data-n') === s.n);
  if (idx === 3) {
    document.getElementById('oscillateInput').checked = true;
    startOscillation();
  } else {
    document.getElementById('oscillateInput').checked = false;
    stopOscillation();
  }
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (idx + 1) + ' / ' + steps.length;
}
function nextStep() { goToStep(Math.min(currentStep + 1, steps.length - 1)); }
function prevStep() { goToStep(Math.max(currentStep - 1, 0)); }

goToStep(0);
window.__markRendered();
